// SPDX-License-Identifier: MIT
pragma solidity ^0.8.15;

import "./LibUDT.sol";

/// @notice The current status of the dispute game.
    enum GameStatus {
        // The game is currently in progress, and has not been resolved.
        IN_PROGRESS,
        // The game has concluded, and the `rootClaim` was challenged successfully.
        CHALLENGER_WINS,
        // The game has concluded, and the `rootClaim` could not be contested.
        DEFENDER_WINS
    }

/// @notice Represents an L2 output root and the L2 block number at which it was generated.
/// @custom:field root The output root.
/// @custom:field l2BlockNumber The L2 block number at which the output root was generated.
    struct OutputRoot {
        Hash root;
        uint256 l2BlockNumber;
    }

/// @title GameTypes
/// @notice A library that defines the IDs of games that can be played.
library GameTypes {
    /// @dev A dispute game type the uses the cannon vm.
    GameType internal constant CANNON = GameType.wrap(0);

    /// @dev A permissioned dispute game type the uses the cannon vm.
    GameType internal constant PERMISSIONED_CANNON = GameType.wrap(1);

    /// @notice A dispute game type the uses the asterisc VM
    GameType internal constant ASTERISC = GameType.wrap(2);

    /// @notice A dispute game type with short game duration for testing withdrawals.
    ///         Not intended for production use.
    GameType internal constant FAST = GameType.wrap(254);

    /// @notice A dispute game type that uses an alphabet vm.
    ///         Not intended for production use.
    GameType internal constant ALPHABET = GameType.wrap(255);
}

/// @title VMStatuses
/// @notice Named type aliases for the various valid VM status bytes.
library VMStatuses {
    /// @notice The VM has executed successfully and the outcome is valid.
    VMStatus internal constant VALID = VMStatus.wrap(0);

    /// @notice The VM has executed successfully and the outcome is invalid.
    VMStatus internal constant INVALID = VMStatus.wrap(1);

    /// @notice The VM has paniced.
    VMStatus internal constant PANIC = VMStatus.wrap(2);

    /// @notice The VM execution is still in progress.
    VMStatus internal constant UNFINISHED = VMStatus.wrap(3);
}

/// @title LocalPreimageKey
/// @notice Named type aliases for local `PreimageOracle` key identifiers.
library LocalPreimageKey {
    /// @notice The identifier for the L1 head hash.
    uint256 internal constant L1_HEAD_HASH = 0x01;

    /// @notice The identifier for the starting output root.
    uint256 internal constant STARTING_OUTPUT_ROOT = 0x02;

    /// @notice The identifier for the disputed output root.
    uint256 internal constant DISPUTED_OUTPUT_ROOT = 0x03;

    /// @notice The identifier for the disputed L2 block number.
    uint256 internal constant DISPUTED_L2_BLOCK_NUMBER = 0x04;

    /// @notice The identifier for the chain ID.
    uint256 internal constant CHAIN_ID = 0x05;
}

contracts/L1/dispute/LockingPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.15;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {MetisConfig} from "../config/MetisConfig.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IDisputeGameFactory} from "../dispute/interfaces/IDisputeGameFactory.sol";
import {IFaultDisputeGame} from "../dispute/interfaces/IFaultDisputeGame.sol";
import {IDisputeGame} from "../dispute/interfaces/IDisputeGame.sol";
import "contracts/L1/dispute/lib/Types.sol";
import "contracts/L1/dispute/lib/Errors.sol";
import {ILockingPool} from "./interfaces/ILockingPool.sol";
import {Lib_AddressManager} from "../../libraries/resolver/Lib_AddressManager.sol";

/// @title LockingPool
/// @notice A locking pool contract that allows users to lock tokens with a delayed withdrawal mechanism
/// @dev Based on DelayedWETH's delayed withdrawal mechanism
contract LockingPool is OwnableUpgradeable, ILockingPool {
    using SafeERC20 for IERC20;

    /// @notice Struct representing a withdrawal request
    struct WithdrawalRequest {
        uint256 amount;
        uint256 timestamp;
    }

    string public constant DISPUTE_GAME_FACTORY_NAME = "DisputeGameFactory";

    /// @notice The token being locked in the pool
    IERC20 public token;

    /// @notice The withdrawal delay period in seconds
    uint256 public lockPeriod;

    /// @notice The slash ratio (base 10000, i.e., 100.00%)
    uint256 public slashRatio;

    /// @notice The MetisConfig contract
    MetisConfig public config;

    /// @notice The Address Manager contract
    Lib_AddressManager public addressManager;

    /// @notice Mapping of user withdrawal requests
    mapping(address => WithdrawalRequest) public withdrawals;

    /// @notice Mapping of user balances
    mapping(address => uint256) public balanceOf;

    /// @notice Total amount of tokens locked
    uint256 public totalLocked;

    /// @notice Array of sequencer addresses
    address[] public depositedSequencers;

    /// @notice Emitted when tokens are deposited
    event Deposit(address indexed user, uint256 amount);

    /// @notice Emitted when a withdrawal is requested
    event Unlock(address indexed user, uint256 amount);

    /// @notice Emitted when tokens are withdrawn
    event Withdraw(address indexed user, uint256 amount);

    /// @notice Emitted when tokens are slashed
    event Slashed(address indexed recipient, uint256 amount);

    /// @notice Emitted when slash ratio is updated
    event SlashRatioUpdated(uint256 oldRatio, uint256 newRatio);

    /// @notice Emitted when lock period is updated
    event LockPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);

    constructor() {
        initialize(address(0), address(0), 0,0,
            Lib_AddressManager(address(0)), MetisConfig(address(0)));
    }

    /// @notice Initializes the contract
    /// @param _owner The owner address
    /// @param _token The ERC20 token contract address
    /// @param _lockPeriod Initial lock period in seconds
    /// @param _slashRatio Initial slash ratio (base 10000)
    /// @param _addressManager The AddressManager contract address
    /// @param _config The MetisConfig contract address
    function initialize(address _owner,
        address _token,
        uint256 _lockPeriod,
        uint256 _slashRatio,
        Lib_AddressManager _addressManager,
        MetisConfig _config) public initializer {
        __Ownable_init();
        _transferOwnership(_owner);

        require(slashRatio <= 10000, "LockingPool: invalid slash ratio");

        token = IERC20(_token);
        lockPeriod = _lockPeriod;
        slashRatio = _slashRatio;
        addressManager = _addressManager;
        config = _config;

        emit SlashRatioUpdated(0, _slashRatio);
        emit LockPeriodUpdated(0, _lockPeriod);
    }

    /// @notice Deposits tokens into the pool
    /// @param _amount Amount of tokens to deposit
    function deposit(uint256 _amount) external {
        require(_amount > 0, "LockingPool: zero deposit");

        token.safeTransferFrom(msg.sender, address(this), _amount);
        balanceOf[msg.sender] += _amount;
        totalLocked += _amount;

        bool depositedBefore = false;
        for (uint256 i = 0; i < depositedSequencers.length; i++) {
            if (depositedSequencers[i] == msg.sender) {
                depositedBefore = true;
                break;
            }
        }

        if (!depositedBefore) {
            depositedSequencers.push(msg.sender);
        }

        emit Deposit(msg.sender, _amount);
    }

    /// @notice Requests to unlock tokens
    /// @param _amount Amount of tokens to unlock
    function unlock(uint256 _amount) external {
        WithdrawalRequest storage wd = withdrawals[msg.sender];
        uint256 newAmount = wd.amount + _amount;

        require(balanceOf[msg.sender] >= newAmount, "LockingPool: insufficient balance");

        wd.timestamp = block.timestamp;
        wd.amount = newAmount;

        emit Unlock(msg.sender, _amount);
    }

    /// @notice Withdraws unlocked tokens
    /// @param _amount Amount of tokens to withdraw
    function withdraw(uint256 _amount) external {
        require(!config.paused(), "LockingPool: contract is paused");

        WithdrawalRequest storage wd = withdrawals[msg.sender];
        require(wd.amount >= _amount, "LockingPool: insufficient unlocked withdrawal");
        require(wd.timestamp > 0, "LockingPool: withdrawal not unlocked");
        require(
            wd.timestamp + lockPeriod <= block.timestamp,
            "LockingPool: withdrawal delay not met"
        );

        wd.amount -= _amount;
        balanceOf[msg.sender] -= _amount;
        totalLocked -= _amount;

        // remove sender from deposited sequencers if balance is zero
        if (balanceOf[msg.sender] == 0) {
            for (uint256 i = 0; i < depositedSequencers.length; i++) {
                if (depositedSequencers[i] == msg.sender) {
                    depositedSequencers[i] = depositedSequencers[depositedSequencers.length - 1];
                    depositedSequencers.pop();
                    break;
                }
            }
        }

        token.safeTransfer(msg.sender, _amount);
        emit Withdraw(msg.sender, _amount);
    }

    /// @notice Slashes a percentage of tokens from the pool
    /// @param _recipient Address to receive the slashed tokens
    function slash(address _recipient) external {
        require(_recipient != address(0), "LockingPool: invalid recipient");
        require(totalLocked > 0, "LockingPool: no tokens to slash");

        // Verify the caller is a valid dispute game
        IFaultDisputeGame game = IFaultDisputeGame(msg.sender);
        (GameType gameType, Claim rootClaim, bytes memory extraData) = game.gameData();

        // Get the verified address of the game based on the game data
        IDisputeGameFactory disputeGameFactory = IDisputeGameFactory(addressManager.getAddress(DISPUTE_GAME_FACTORY_NAME));
        require(address(disputeGameFactory) != address(0), "LockingPool: dispute game factory not set");
        (IDisputeGame factoryRegisteredGame,) = disputeGameFactory.games({
            _gameType: gameType,
            _rootClaim: rootClaim,
            _extraData: extraData
        });

        // Must be a valid game
        if (address(factoryRegisteredGame) != address(game)) revert UnregisteredGame();

        // Must be a game that resolved in favor of the challenger
        if (game.status() != GameStatus.CHALLENGER_WINS) {
            revert InvalidGameStatus();
        }

        // Track actual slashed amount
        uint256 actualSlashedAmount;

        // Cache users array to avoid multiple storage reads
        address[] memory users = depositedSequencers;
        uint256 usersLength = users.length;

        // First pass: calculate actual slashed amount
        for (uint256 i; i < usersLength;) {
            address user = users[i];
            uint256 userBalance = balanceOf[user];
            if (userBalance > 0) {
                // Calculate user's slash amount
                uint256 userSlashAmount = (userBalance * slashRatio) / 10000;
                if (userSlashAmount > 0) {
                    actualSlashedAmount += userSlashAmount;
                    // Update user balance
                    balanceOf[user] = userBalance - userSlashAmount;
                }
            }
            // Gas optimization for loops
            unchecked { ++i; }
        }

        // Require some tokens were actually slashed
        require(actualSlashedAmount > 0, "LockingPool: slash amount too small");

        // Update total locked amount
        totalLocked -= actualSlashedAmount;

        // Transfer the actual slashed amount
        token.safeTransfer(_recipient, actualSlashedAmount);
        emit Slashed(_recipient, actualSlashedAmount);
    }

    /// @notice Updates the slash ratio
    /// @param _newRatio New slash ratio (base 10000)
    function setSlashRatio(uint256 _newRatio) external onlyOwner {
        require(_newRatio <= 10000, "LockingPool: invalid slash ratio");

        uint256 oldRatio = slashRatio;
        slashRatio = _newRatio;
        emit SlashRatioUpdated(oldRatio, _newRatio);
    }

    /// @notice Updates the lock period
    /// @param _newPeriod New lock period in seconds
    function setLockPeriod(uint256 _newPeriod) external onlyOwner {
        uint256 oldPeriod = lockPeriod;
        lockPeriod = _newPeriod;
        emit LockPeriodUpdated(oldPeriod, _newPeriod);
    }

    /// @notice Gets the withdrawal request details for a user
    /// @param _user User address
    /// @return amount Amount requested for withdrawal
    /// @return timestamp Timestamp of the withdrawal request
    function getWithdrawalRequest(address _user) 
        external 
        view 
        returns (uint256 amount, uint256 timestamp) 
    {
        WithdrawalRequest memory wd = withdrawals[_user];
        return (wd.amount, wd.timestamp);
    }
}

contracts/L1/dispute/PermissionedDispute.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.15;

import {IDelayedWMetis} from "./interfaces/IDelayedWMetis.sol";
import { FaultDisputeGame, IFaultDisputeGame, IBigStepper, IInitializable } from "contracts/L1/dispute/FaultDisputeGame.sol";
import { Lib_AddressManager } from "../../libraries/resolver/Lib_AddressManager.sol";
import "contracts/L1/dispute/lib/Types.sol";
import "contracts/L1/dispute/lib/Errors.sol";

/// @title PermissionedDisputeGame
/// @notice PermissionedDisputeGame is a contract that inherits from `FaultDisputeGame`, and contains two roles:
///         - The `challenger` role, which is allowed to challenge a dispute.
///         - The `proposer` role, which is allowed to create proposals and participate in their game.
///         This contract exists as a way for networks to support the fault proof iteration of the OptimismPortal
///         contract without needing to support a fully permissionless system. Permissionless systems can introduce
///         costs that certain networks may not wish to support. This contract can also be used as a fallback mechanism
///         in case of a failure in the permissionless fault proof system in the stage one release.
contract PermissionedDisputeGame is FaultDisputeGame {
    /// @notice The proposer role is allowed to create proposals and participate in the dispute game.
    address internal immutable PROPOSER;

    /// @notice The challenger role is allowed to participate in the dispute game.
    address internal immutable CHALLENGER;

    /// @notice Modifier that gates access to the `challenger` and `proposer` roles.
    modifier onlyAuthorized() {
        if (!(msg.sender == PROPOSER || msg.sender == CHALLENGER)) {
            revert BadAuth();
        }
        _;
    }

    /// @param _gameType The type ID of the game.
    /// @param _absolutePrestate The absolute prestate of the instruction trace.
    /// @param _maxGameDepth The maximum depth of bisection.
    /// @param _splitDepth The final depth of the output bisection portion of the game.
    /// @param _clockExtension The clock extension to perform when the remaining duration is less than the extension.
    /// @param _maxClockDuration The maximum amount of time that may accumulate on a team's chess clock.
    /// @param _vm An onchain VM that performs single instruction steps on an FPP trace.
    /// @param _wmetis WMETIS contract for holding METIS.
    /// @param _addressManager Address manager contract.
    /// @param _l2ChainId Chain ID of the L2 network this contract argues about.
    /// @param _proposer Address that is allowed to create instances of this contract.
    /// @param _challenger Address that is allowed to challenge instances of this contract.
    constructor(
        GameType _gameType,
        Claim _absolutePrestate,
        uint256 _maxGameDepth,
        uint256 _splitDepth,
        Duration _clockExtension,
        Duration _maxClockDuration,
        IBigStepper _vm,
        IDelayedWMetis _wmetis,
        Lib_AddressManager _addressManager,
        uint256 _l2ChainId,
        address _proposer,
        address _challenger
    )
    FaultDisputeGame(
    _gameType,
    _absolutePrestate,
    _maxGameDepth,
    _splitDepth,
    _clockExtension,
    _maxClockDuration,
    _vm,
    _wmetis,
    _addressManager,
    _l2ChainId
    )
    {
        PROPOSER = _proposer;
        CHALLENGER = _challenger;
    }

    /// @inheritdoc IFaultDisputeGame
    function step(
        uint256 _claimIndex,
        bool _isAttack,
        bytes calldata _stateData,
        bytes calldata _proof
    )
    public
    override
    onlyAuthorized
    {
        super.step(_claimIndex, _isAttack, _stateData, _proof);
    }

    /// @notice Generic move function, used for both `attack` and `defend` moves.
    /// @notice _disputed The disputed `Claim`.
    /// @param _challengeIndex The index of the claim being moved against. This must match the `_disputed` claim.
    /// @param _claim The claim at the next logical position in the game.
    /// @param _isAttack Whether or not the move is an attack or defense.
    function move(
        Claim _disputed,
        uint256 _challengeIndex,
        Claim _claim,
        bool _isAttack
    )
    public
    override
    onlyAuthorized
    {
        super.move(_disputed, _challengeIndex, _claim, _isAttack);
    }

    /// @inheritdoc IInitializable
    function initialize() public payable override {
        // The creator of the dispute game must be the proposer EOA.
        if (tx.origin != PROPOSER) revert BadAuth();

        // Fallthrough initialization.
        super.initialize();
    }

    ////////////////////////////////////////////////////////////////
    //                     IMMUTABLE GETTERS                      //
    ////////////////////////////////////////////////////////////////

    /// @notice Returns the proposer address.
    function proposer() external view returns (address proposer_) {
        proposer_ = PROPOSER;
    }

    /// @notice Returns the challenger address.
    function challenger() external view returns (address challenger_) {
        challenger_ = CHALLENGER;
    }
}

